mapper.select:
SELECT user_id, subscribe_time, unsubscribe_time, expiration_time, inviter_id, member_level
FROM fans
WHERE user_id = #{userId}

mapper.update:
UPDATE fans
SET subscribe_time = #{subscribeTime}, unsubscribe_time = #{unsubscribeTime},
    expiration_time = #{expirationTime}, inviter_id = #{inviterId}, member_level = #{memberLevel}
WHERE user_id = #{userId}
